/**
 * Local stand-in for @deepseek-ai/dsh-home-paths (DSH-internal utility).
 * The vendored bundle only uses resolveDshHome() to place its own state
 * files (credential refresh copy, catalog cache, probe records). Keeping
 * the same default (~/.dsh) means the bridge and the DSH plugin share
 * those files exactly as they would inside one install.
 */
import { homedir } from "node:os";
import { join } from "node:path";

export function resolveDshHome() {
  const fromEnv = process.env.DSH_HOME?.trim();
  if (fromEnv) return fromEnv;
  return join(homedir(), ".dsh");
}
